#!/usr/bin/env python3
from __future__ import annotations

import shutil
import sys
from datetime import datetime
from pathlib import Path

ROOT = Path.cwd()
REQUIRED = [ROOT / 'legacy_app.py', ROOT / 'plg_core' / 'application.py', ROOT / 'templates' / 'base.html']
for path in REQUIRED:
    if not path.exists():
        sys.exit(f'ERROR: Run this installer from the PLG-Core project folder. Missing: {path.relative_to(ROOT)}')

stamp = datetime.now().strftime('%Y%m%d-%H%M%S')
backup = ROOT / f'backup-commit-0010-{stamp}'
backup.mkdir(parents=True)

files_to_backup = [
    'legacy_app.py', 'plg_core/application.py', 'plg_core/database/migrations.py',
    'templates/base.html', 'templates/new_job.html', 'templates/customer_account.html',
    'static/app.css', 'CHANGELOG.md', 'VERSION'
]
for rel in files_to_backup:
    src = ROOT / rel
    if src.exists():
        dst = backup / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dst)


def replace_once(path: Path, old: str, new: str) -> None:
    text = path.read_text()
    if old not in text:
        raise RuntimeError(f'Expected code block not found in {path.relative_to(ROOT)}. No changes were applied to that file.')
    path.write_text(text.replace(old, new, 1))

# 1) Database migration
mig = ROOT / 'plg_core/database/migrations.py'
text = mig.read_text()
if '_migration_0002_machine_registry' not in text:
    insert = '''\n\ndef _migration_0002_machine_registry(connection: sqlite3.Connection) -> None:\n    connection.executescript(\n        """\n        CREATE TABLE IF NOT EXISTS machines (\n            id INTEGER PRIMARY KEY AUTOINCREMENT,\n            customer_id INTEGER NOT NULL,\n            machine_number TEXT UNIQUE,\n            name TEXT NOT NULL DEFAULT '',\n            manufacturer TEXT NOT NULL DEFAULT '',\n            model TEXT NOT NULL DEFAULT '',\n            year TEXT NOT NULL DEFAULT '',\n            vin_pin_serial TEXT NOT NULL DEFAULT '',\n            engine TEXT NOT NULL DEFAULT '',\n            engine_serial TEXT NOT NULL DEFAULT '',\n            transmission TEXT NOT NULL DEFAULT '',\n            component_details TEXT NOT NULL DEFAULT '',\n            notes TEXT NOT NULL DEFAULT '',\n            active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),\n            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n            updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n            FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE\n        );\n\n        CREATE INDEX IF NOT EXISTS idx_machines_customer_id ON machines(customer_id);\n        CREATE INDEX IF NOT EXISTS idx_machines_identifier ON machines(vin_pin_serial);\n        """\n    )\n\n    job_columns = {row["name"] for row in connection.execute("PRAGMA table_info(jobs)").fetchall()}\n    if "machine_id" not in job_columns:\n        connection.execute("ALTER TABLE jobs ADD COLUMN machine_id INTEGER REFERENCES machines(id)")\n\n    old_jobs = connection.execute(\n        """\n        SELECT id, customer_id, manufacturer, machine, pin_serial\n        FROM jobs\n        WHERE customer_id IS NOT NULL AND machine_id IS NULL\n          AND (TRIM(COALESCE(manufacturer, '')) <> ''\n               OR TRIM(COALESCE(machine, '')) <> ''\n               OR TRIM(COALESCE(pin_serial, '')) <> '')\n        ORDER BY id\n        """\n    ).fetchall()\n\n    for job in old_jobs:\n        existing = connection.execute(\n            """\n            SELECT id FROM machines\n            WHERE customer_id = ?\n              AND LOWER(TRIM(manufacturer)) = LOWER(TRIM(?))\n              AND LOWER(TRIM(model)) = LOWER(TRIM(?))\n              AND LOWER(TRIM(vin_pin_serial)) = LOWER(TRIM(?))\n            ORDER BY id LIMIT 1\n            """,\n            (job["customer_id"], job["manufacturer"] or "", job["machine"] or "", job["pin_serial"] or ""),\n        ).fetchone()\n        if existing:\n            machine_id = existing["id"]\n        else:\n            display_name = " ".join(\n                part for part in [job["manufacturer"] or "", job["machine"] or ""] if part.strip()\n            ).strip() or (job["pin_serial"] or "Machine")\n            cursor = connection.execute(\n                """\n                INSERT INTO machines (customer_id, name, manufacturer, model, vin_pin_serial)\n                VALUES (?, ?, ?, ?, ?)\n                """,\n                (job["customer_id"], display_name, job["manufacturer"] or "", job["machine"] or "", job["pin_serial"] or ""),\n            )\n            machine_id = cursor.lastrowid\n            connection.execute(\n                "UPDATE machines SET machine_number = ? WHERE id = ?",\n                (f"PLG-M{machine_id:05d}", machine_id),\n            )\n        connection.execute("UPDATE jobs SET machine_id = ? WHERE id = ?", (machine_id, job["id"]))\n'''
    text = text.replace('\n\nMIGRATIONS: list[Migration] = [', insert + '\n\nMIGRATIONS: list[Migration] = [', 1)
    text = text.replace('("0001_basket_foundation", _migration_0001_basket_foundation),\n]', '("0001_basket_foundation", _migration_0001_basket_foundation),\n    ("0002_machine_registry", _migration_0002_machine_registry),\n]', 1)
    mig.write_text(text)

# 2) Machine module
machine_dir = ROOT / 'plg_core/machines'
machine_dir.mkdir(parents=True, exist_ok=True)
(machine_dir / '__init__.py').write_text('from .routes import router\n\n__all__ = ["router"]\n')
(machine_dir / 'routes.py').write_text('''from __future__ import annotations\n\nfrom contextlib import closing\nfrom typing import Annotated\n\nfrom fastapi import APIRouter, Form, HTTPException, Request\nfrom fastapi.responses import HTMLResponse, RedirectResponse\n\nfrom legacy_app import get_connection, templates\n\nrouter = APIRouter()\n\n\n@router.get("/machines", response_class=HTMLResponse)\ndef list_machines(request: Request, view: str = "active"):\n    if view not in {"active", "inactive", "all"}:\n        view = "active"\n    where = "" if view == "all" else ("WHERE machines.active=1" if view == "active" else "WHERE machines.active=0")\n    with closing(get_connection()) as connection:\n        machines = connection.execute(\n            f"""\n            SELECT machines.*, customers.name AS customer_name, customers.company AS customer_company,\n                   COUNT(DISTINCT jobs.id) AS jobs_count\n            FROM machines\n            JOIN customers ON customers.id = machines.customer_id\n            LEFT JOIN jobs ON jobs.machine_id = machines.id\n            {where}\n            GROUP BY machines.id\n            ORDER BY machines.updated_at DESC, machines.id DESC\n            """\n        ).fetchall()\n    return templates.TemplateResponse(request=request, name="machines.html", context={"machines": machines, "view": view, "active_page": "machines"})\n\n\n@router.get("/machines/new", response_class=HTMLResponse)\ndef new_machine_form(request: Request, customer_id: int | None = None):\n    with closing(get_connection()) as connection:\n        customers = connection.execute("SELECT * FROM customers WHERE active=1 ORDER BY name COLLATE NOCASE").fetchall()\n    return templates.TemplateResponse(request=request, name="machine_form.html", context={"machine": None, "customers": customers, "selected_customer_id": customer_id, "active_page": "machines"})\n\n\n@router.post("/machines/new")\ndef create_machine(\n    customer_id: Annotated[int, Form()],\n    name: Annotated[str, Form()] = "",\n    manufacturer: Annotated[str, Form()] = "",\n    model: Annotated[str, Form()] = "",\n    year: Annotated[str, Form()] = "",\n    vin_pin_serial: Annotated[str, Form()] = "",\n    engine: Annotated[str, Form()] = "",\n    engine_serial: Annotated[str, Form()] = "",\n    transmission: Annotated[str, Form()] = "",\n    component_details: Annotated[str, Form()] = "",\n    notes: Annotated[str, Form()] = "",\n):\n    display_name = name.strip() or " ".join(p for p in [manufacturer.strip(), model.strip()] if p).strip() or vin_pin_serial.strip()\n    if not display_name:\n        raise HTTPException(status_code=400, detail="Machine name, model, or identifier is required.")\n    with closing(get_connection()) as connection:\n        customer = connection.execute("SELECT id FROM customers WHERE id=? AND active=1", (customer_id,)).fetchone()\n        if customer is None:\n            raise HTTPException(status_code=400, detail="Customer not found.")\n        cursor = connection.execute(\n            """INSERT INTO machines\n            (customer_id,name,manufacturer,model,year,vin_pin_serial,engine,engine_serial,transmission,component_details,notes)\n            VALUES (?,?,?,?,?,?,?,?,?,?,?)""",\n            (customer_id,display_name,manufacturer.strip(),model.strip(),year.strip(),vin_pin_serial.strip(),engine.strip(),engine_serial.strip(),transmission.strip(),component_details.strip(),notes.strip()),\n        )\n        machine_id = cursor.lastrowid\n        connection.execute("UPDATE machines SET machine_number=? WHERE id=?", (f"PLG-M{machine_id:05d}", machine_id))\n        connection.commit()\n    return RedirectResponse(url=f"/machines/{machine_id}", status_code=303)\n\n\n@router.get("/machines/{machine_id}", response_class=HTMLResponse)\ndef machine_detail(request: Request, machine_id: int):\n    with closing(get_connection()) as connection:\n        machine = connection.execute(\n            """SELECT machines.*, customers.name AS customer_name, customers.company AS customer_company\n               FROM machines JOIN customers ON customers.id=machines.customer_id WHERE machines.id=?""",\n            (machine_id,),\n        ).fetchone()\n        if machine is None:\n            raise HTTPException(status_code=404, detail="Machine not found.")\n        jobs = connection.execute("SELECT * FROM jobs WHERE machine_id=? ORDER BY id DESC", (machine_id,)).fetchall()\n        quotes = connection.execute("SELECT quotes.* FROM quotes JOIN jobs ON jobs.id=quotes.job_id WHERE jobs.machine_id=? ORDER BY quotes.id DESC", (machine_id,)).fetchall()\n        invoices = connection.execute("SELECT invoices.* FROM invoices JOIN jobs ON jobs.id=invoices.job_id WHERE jobs.machine_id=? ORDER BY invoices.id DESC", (machine_id,)).fetchall()\n    return templates.TemplateResponse(request=request, name="machine_detail.html", context={"machine": machine, "jobs": jobs, "quotes": quotes, "invoices": invoices, "active_page": "machines"})\n\n\n@router.get("/machines/{machine_id}/edit", response_class=HTMLResponse)\ndef edit_machine_form(request: Request, machine_id: int):\n    with closing(get_connection()) as connection:\n        machine = connection.execute("SELECT * FROM machines WHERE id=?", (machine_id,)).fetchone()\n        if machine is None:\n            raise HTTPException(status_code=404, detail="Machine not found.")\n        customers = connection.execute("SELECT * FROM customers WHERE active=1 ORDER BY name COLLATE NOCASE").fetchall()\n    return templates.TemplateResponse(request=request, name="machine_form.html", context={"machine": machine, "customers": customers, "selected_customer_id": machine["customer_id"], "active_page": "machines"})\n\n\n@router.post("/machines/{machine_id}/edit")\ndef update_machine(\n    machine_id: int, customer_id: Annotated[int, Form()], name: Annotated[str, Form()] = "",\n    manufacturer: Annotated[str, Form()] = "", model: Annotated[str, Form()] = "", year: Annotated[str, Form()] = "",\n    vin_pin_serial: Annotated[str, Form()] = "", engine: Annotated[str, Form()] = "", engine_serial: Annotated[str, Form()] = "",\n    transmission: Annotated[str, Form()] = "", component_details: Annotated[str, Form()] = "", notes: Annotated[str, Form()] = "",\n):\n    display_name = name.strip() or " ".join(p for p in [manufacturer.strip(), model.strip()] if p).strip() or vin_pin_serial.strip()\n    if not display_name:\n        raise HTTPException(status_code=400, detail="Machine name, model, or identifier is required.")\n    with closing(get_connection()) as connection:\n        connection.execute(\n            """UPDATE machines SET customer_id=?,name=?,manufacturer=?,model=?,year=?,vin_pin_serial=?,engine=?,engine_serial=?,\n               transmission=?,component_details=?,notes=?,updated_at=CURRENT_TIMESTAMP WHERE id=?""",\n            (customer_id,display_name,manufacturer.strip(),model.strip(),year.strip(),vin_pin_serial.strip(),engine.strip(),engine_serial.strip(),transmission.strip(),component_details.strip(),notes.strip(),machine_id),\n        )\n        connection.execute(\n            """UPDATE jobs SET customer_id=?, manufacturer=?, machine=?, pin_serial=?\n               WHERE machine_id=?""",\n            (customer_id, manufacturer.strip(), model.strip(), vin_pin_serial.strip(), machine_id),\n        )\n        connection.commit()\n    return RedirectResponse(url=f"/machines/{machine_id}", status_code=303)\n\n\n@router.post("/machines/{machine_id}/status")\ndef machine_status(machine_id: int, active: Annotated[int, Form()]):\n    with closing(get_connection()) as connection:\n        connection.execute("UPDATE machines SET active=?,updated_at=CURRENT_TIMESTAMP WHERE id=?", (1 if active else 0, machine_id))\n        connection.commit()\n    return RedirectResponse(url=f"/machines/{machine_id}", status_code=303)\n''')

# 3) Include router
app_path = ROOT / 'plg_core/application.py'
app_text = app_path.read_text()
if 'plg_core.machines.routes' not in app_text:
    app_text = app_text.replace('from plg_core.basket.routes import router as basket_router\n', 'from plg_core.basket.routes import router as basket_router\nfrom plg_core.machines.routes import router as machines_router\n')
    app_text = app_text.replace('app.include_router(basket_router)\n', 'app.include_router(basket_router)\napp.include_router(machines_router)\n')
    app_text = app_text.replace('"version": "1.0.0-alpha.1-sprint-1",', '"version": "1.1.0-alpha.1-sprint-2",')
    app_path.write_text(app_text)

# 4) Legacy job/customer integration
legacy = ROOT / 'legacy_app.py'
legacy_text = legacy.read_text()
if 'selected_machine_id' not in legacy_text:
    old = '''@app.get("/jobs/new", response_class=HTMLResponse)\ndef new_job_form(request: Request, customer_id: int | None = None):\n    with closing(get_connection()) as connection:\n        customers=connection.execute("SELECT * FROM customers WHERE active=1 ORDER BY name COLLATE NOCASE, company COLLATE NOCASE").fetchall()\n    return templates.TemplateResponse(request=request,name="new_job.html",context={"customers":customers,"selected_customer_id":customer_id,"active_page":"jobs"})\n'''
    new = '''@app.get("/jobs/new", response_class=HTMLResponse)\ndef new_job_form(request: Request, customer_id: int | None = None, machine_id: int | None = None):\n    with closing(get_connection()) as connection:\n        customers=connection.execute("SELECT * FROM customers WHERE active=1 ORDER BY name COLLATE NOCASE, company COLLATE NOCASE").fetchall()\n        machines=connection.execute("SELECT * FROM machines WHERE active=1 ORDER BY name COLLATE NOCASE, id DESC").fetchall()\n    return templates.TemplateResponse(request=request,name="new_job.html",context={"customers":customers,"machines":machines,"selected_customer_id":customer_id,"selected_machine_id":machine_id,"active_page":"jobs"})\n'''
    if old not in legacy_text:
        raise RuntimeError('Could not locate new_job_form in legacy_app.py')
    legacy_text = legacy_text.replace(old, new, 1)

    legacy_text = legacy_text.replace('''    customer_id: Annotated[int | None, Form()] = None,\n    company:''', '''    customer_id: Annotated[int | None, Form()] = None,\n    machine_id: Annotated[int | None, Form()] = None,\n    company:''', 1)

    old_insert = '''        job_number=next_job_number(connection)\n        cur=connection.execute("""\n            INSERT INTO jobs (job_number,created_date,customer_id,customer,company,phone,email,address,manufacturer,machine,pin_serial,status,notes)\n            VALUES (?,?,?,?,?,?,?,?,?,?,?,'REQUESTED',?)\n        """,(job_number,date.today().isoformat(),customer_row["id"],customer_row["name"],customer_row["company"] or "",customer_row["phone"] or "",customer_row["email"] or "",customer_row["address"] or "",manufacturer.strip(),machine.strip(),pin_serial.strip(),notes.strip()))\n'''
    new_insert = '''        if machine_id:\n            machine_row=connection.execute("SELECT * FROM machines WHERE id=? AND customer_id=? AND active=1",(machine_id,customer_row["id"])).fetchone()\n            if machine_row is None:\n                raise HTTPException(status_code=400,detail="Selected machine not found for this customer.")\n            manufacturer_value=machine_row["manufacturer"] or ""\n            machine_value=machine_row["model"] or machine_row["name"] or ""\n            pin_serial_value=machine_row["vin_pin_serial"] or ""\n        else:\n            manufacturer_value=manufacturer.strip()\n            machine_value=machine.strip()\n            pin_serial_value=pin_serial.strip()\n            machine_id=None\n            if manufacturer_value or machine_value or pin_serial_value:\n                display_name=" ".join(part for part in [manufacturer_value,machine_value] if part).strip() or pin_serial_value\n                machine_cursor=connection.execute("INSERT INTO machines (customer_id,name,manufacturer,model,vin_pin_serial) VALUES (?,?,?,?,?)",(customer_row["id"],display_name,manufacturer_value,machine_value,pin_serial_value))\n                machine_id=machine_cursor.lastrowid\n                connection.execute("UPDATE machines SET machine_number=? WHERE id=?",(f"PLG-M{machine_id:05d}",machine_id))\n        job_number=next_job_number(connection)\n        cur=connection.execute("""\n            INSERT INTO jobs (job_number,created_date,customer_id,machine_id,customer,company,phone,email,address,manufacturer,machine,pin_serial,status,notes)\n            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,'REQUESTED',?)\n        """,(job_number,date.today().isoformat(),customer_row["id"],machine_id,customer_row["name"],customer_row["company"] or "",customer_row["phone"] or "",customer_row["email"] or "",customer_row["address"] or "",manufacturer_value,machine_value,pin_serial_value,notes.strip()))\n'''
    if old_insert not in legacy_text:
        raise RuntimeError('Could not locate create_job insert block in legacy_app.py')
    legacy_text = legacy_text.replace(old_insert, new_insert, 1)

    old_context = '''        jobs=connection.execute("SELECT * FROM jobs WHERE customer_id=? ORDER BY id DESC",(customer_id,)).fetchall()\n        quotes='''
    new_context = '''        jobs=connection.execute("SELECT * FROM jobs WHERE customer_id=? ORDER BY id DESC",(customer_id,)).fetchall()\n        machines=connection.execute("SELECT * FROM machines WHERE customer_id=? ORDER BY active DESC,updated_at DESC,id DESC",(customer_id,)).fetchall()\n        quotes='''
    legacy_text = legacy_text.replace(old_context, new_context, 1)
    legacy_text = legacy_text.replace('''"customer":customer,"jobs":jobs,"quotes":quotes,''', '''"customer":customer,"machines":machines,"jobs":jobs,"quotes":quotes,''', 1)
    legacy.write_text(legacy_text)

# 5) Templates
