    base_text = base_text.replace('''      <a class="{% if active_page == 'customers' %}active{% endif %}" href="/customers">\n        <span class="nav-icon" aria-hidden="true">♙</span><span>Customers</span>\n      </a>''', '''      <a class="{% if active_page == 'customers' %}active{% endif %}" href="/customers">\n        <span class="nav-icon" aria-hidden="true">♙</span><span>Customers</span>\n      </a>\n      <a class="{% if active_page == 'machines' %}active{% endif %}" href="/machines">\n        <span class="nav-icon" aria-hidden="true">◆</span><span>Machines</span>\n      </a>''', 1)
    base_text = base_text.replace('PLG Core · Version 1.0 Alpha', 'PLG Core · Version 1.1 Alpha')
