(ROOT / 'templates/new_job.html').write_text('''{% extends "base.html" %}\n{% block title %}New Job · PartsLink Global{% endblock %}\n{% block content %}\n<section class="workspace-heading"><div><p class="eyebrow">NEW JOB</p><h1>Create a Job</h1><p>Select an existing customer and machine, or create either one as needed.</p></div></section>\n<section class="new-job-flow"><span class="active">1. Job Information</span><span>2. Parts Basket</span><span>3. Checkout</span><span>4. Create Quote</span></section>\n<form method="post" action="/jobs" class="panel form-grid streamlined-job-form">\n<div class="form-section"><p class="eyebrow">CUSTOMER</p><h2>Customer Information</h2>\n<label>Existing Customer<select name="customer_id" id="customer-selector"><option value="">+ Create New Customer</option>{% for customer in customers %}<option value="{{ customer.id }}" data-name="{{ customer.name|e }}" data-company="{{ (customer.company or '')|e }}" data-phone="{{ (customer.phone or '')|e }}" data-email="{{ (customer.email or '')|e }}" data-address="{{ (customer.address or '')|e }}" {% if selected_customer_id == customer.id %}selected{% endif %}>{{ customer.name }}{% if customer.company %} · {{ customer.company }}{% endif %} ({{ customer.customer_number }})</option>{% endfor %}</select></label>\n<label>Customer Name *<input name="customer" id="customer-name" required autofocus></label><label>Company<input name="company" id="customer-company"></label><div class="two-column"><label>Phone<input name="phone" id="customer-phone"></label><label>Email<input name="email" type="email" id="customer-email"></label></div><label>Address<input name="address" id="customer-address"></label></div>\n<div class="form-section"><p class="eyebrow">EQUIPMENT</p><h2>Machine or Vehicle</h2>\n<label>Existing Machine<select name="machine_id" id="machine-selector"><option value="">+ Add New Machine From This Job</option>{% for item in machines %}<option value="{{ item.id }}" data-customer-id="{{ item.customer_id }}" data-manufacturer="{{ item.manufacturer|e }}" data-model="{{ item.model|e }}" data-identifier="{{ item.vin_pin_serial|e }}" {% if selected_machine_id == item.id %}selected{% endif %}>{{ item.name }}{% if item.vin_pin_serial %} · {{ item.vin_pin_serial }}{% endif %}</option>{% endfor %}</select></label>\n<div class="two-column"><label>Manufacturer<input name="manufacturer" id="machine-manufacturer" placeholder="CAT"></label><label>Model / Machine<input name="machine" id="machine-model" placeholder="420D Backhoe Loader"></label></div><label>VIN / PIN / Serial<input name="pin_serial" id="machine-identifier" placeholder="FDP15598"></label><small class="field-help">When no existing machine is selected, PLG creates a reusable machine profile automatically.</small></div>\n<div class="form-actions full streamlined-job-actions"><a class="button ghost" href="/jobs">Cancel</a><button class="button" type="submit">Create Job &amp; Open Parts Basket →</button></div>\n</form>\n<script>(()=>{const customer=document.getElementById('customer-selector');const machine=document.getElementById('machine-selector');const cm={name:document.getElementById('customer-name'),company:document.getElementById('customer-company'),phone:document.getElementById('customer-phone'),email:document.getElementById('customer-email'),address:document.getElementById('customer-address')};const mm={manufacturer:document.getElementById('machine-manufacturer'),model:document.getElementById('machine-model'),identifier:document.getElementById('machine-identifier')};const all=[...machine.options].slice(1).map(o=>o.cloneNode(true));function syncCustomer(){const o=customer.options[customer.selectedIndex];const existing=Boolean(customer.value);for(const[k,f]of Object.entries(cm)){f.value=existing?(o.dataset[k]||''):'';f.readOnly=existing;}const selected=machine.value;machine.innerHTML='<option value="">+ Add New Machine From This Job</option>';for(const option of all){if(!existing||option.dataset.customerId===customer.value)machine.appendChild(option.cloneNode(true));}if([...machine.options].some(o=>o.value===selected))machine.value=selected;else machine.value='';syncMachine();}function syncMachine(){const o=machine.options[machine.selectedIndex];const existing=Boolean(machine.value);for(const[k,f]of Object.entries(mm)){f.value=existing?(o.dataset[k]||''):'';f.readOnly=existing;}}customer.addEventListener('change',syncCustomer);machine.addEventListener('change',syncMachine);syncCustomer();{% if selected_machine_id %}machine.value='{{ selected_machine_id }}';syncMachine();{% endif %}})();</script>\n{% endblock %}\n''')

customer_template = ROOT / 'templates/customer_account.html'
ctext = customer_template.read_text()
if 'CUSTOMER MACHINES' not in ctext:
    marker = '<section class="panel">\n  <div class="panel-heading"><div><p class="eyebrow">JOBS</p><h2>Customer Jobs</h2></div></div>'
    block = '''<section class="panel">\n  <div class="panel-heading">\n    <div><p class="eyebrow">CUSTOMER MACHINES</p><h2>Machines &amp; Vehicles</h2></div>\n    <a class="button" href="/machines/new?customer_id={{ customer.id }}">＋ Add Machine</a>\n  </div>\n  {% if machines %}\n  <div class="customer-record-list">\n    {% for machine in machines %}\n    <a class="customer-record-row" href="/machines/{{ machine.id }}">\n      <div><strong>{{ machine.name }}</strong><span>{{ machine.manufacturer }} {{ machine.model }}{% if machine.vin_pin_serial %} · {{ machine.vin_pin_serial }}{% endif %}</span></div>\n      <div><strong>{{ machine.machine_number }}</strong><span>{% if machine.active %}Active{% else %}Inactive{% endif %}</span></div>\n    </a>\n    {% endfor %}\n  </div>\n  {% else %}<p>No machines saved for this customer.</p>{% endif %}\n</section>\n\n'''
    if marker not in ctext:
        raise RuntimeError('Could not locate jobs section in customer_account.html')
    customer_template.write_text(ctext.replace(marker, block + marker, 1))

(ROOT / 'templates/machines.html').write_text('''{% extends "base.html" %}\n{% block title %}Machines · PartsLink Global{% endblock %}\n{% block content %}\n<section class="workspace-heading"><div><p class="eyebrow">MACHINE REGISTRY</p><h1>Machines &amp; Vehicles</h1><p>Reusable equipment profiles connected to customers and jobs.</p></div><a class="button" href="/machines/new">＋ Add Machine</a></section>\n<section class="panel"><div class="filter-links"><a class="{% if view=='active' %}active{% endif %}" href="/machines?view=active">Active</a><a class="{% if view=='inactive' %}active{% endif %}" href="/machines?view=inactive">Inactive</a><a class="{% if view=='all' %}active{% endif %}" href="/machines?view=all">All</a></div></section>\n<section class="panel">{% if machines %}<div class="management-list">{% for machine in machines %}<a class="management-row" href="/machines/{{ machine.id }}"><div><strong>{{ machine.name }}</strong><span>{{ machine.customer_name }}{% if machine.customer_company %} · {{ machine.customer_company }}{% endif %}</span></div><div><strong>{{ machine.manufacturer }} {{ machine.model }}</strong><span>{{ machine.vin_pin_serial or machine.machine_number }}</span></div><div><strong>{{ machine.jobs_count }} job{% if machine.jobs_count != 1 %}s{% endif %}</strong><span>{% if machine.active %}Active{% else %}Inactive{% endif %}</span></div></a>{% endfor %}</div>{% else %}<p>No machines found in this view.</p>{% endif %}</section>\n{% endblock %}\n''')

(ROOT / 'templates/machine_form.html').write_text('''{% extends "base.html" %}\n{% block title %}{% if machine %}Edit {{ machine.name }}{% else %}New Machine{% endif %} · PartsLink Global{% endblock %}\n{% block content %}\n<section class="workspace-heading"><div><p class="eyebrow">MACHINE REGISTRY</p><h1>{% if machine %}Edit Machine{% else %}Add Machine{% endif %}</h1><p>Create one reusable profile for every vehicle, engine, or machine.</p></div></section>\n<form method="post" action="{% if machine %}/machines/{{ machine.id }}/edit{% else %}/machines/new{% endif %}" class="panel form-grid">\n<div class="form-section"><h2>Ownership</h2><label>Customer *<select name="customer_id" required><option value="">Select customer</option>{% for customer in customers %}<option value="{{ customer.id }}" {% if selected_customer_id == customer.id %}selected{% endif %}>{{ customer.name }}{% if customer.company %} · {{ customer.company }}{% endif %}</option>{% endfor %}</select></label><label>Machine Name<input name="name" value="{{ machine.name if machine else '' }}" placeholder="CAT 420D or Detroit 8V92"></label><label>Year<input name="year" value="{{ machine.year if machine else '' }}"></label></div>\n<div class="form-section"><h2>Identification</h2><div class="two-column"><label>Manufacturer<input name="manufacturer" value="{{ machine.manufacturer if machine else '' }}"></label><label>Model<input name="model" value="{{ machine.model if machine else '' }}"></label></div><label>VIN / PIN / Main Serial<input name="vin_pin_serial" value="{{ machine.vin_pin_serial if machine else '' }}"></label></div>\n<div class="form-section"><h2>Powertrain</h2><label>Engine<input name="engine" value="{{ machine.engine if machine else '' }}"></label><label>Engine Serial<input name="engine_serial" value="{{ machine.engine_serial if machine else '' }}"></label><label>Transmission<input name="transmission" value="{{ machine.transmission if machine else '' }}"></label></div>\n<div class="form-section"><h2>Additional Details</h2><label>Component Details<textarea name="component_details" rows="4">{{ machine.component_details if machine else '' }}</textarea></label><label>Notes<textarea name="notes" rows="4">{{ machine.notes if machine else '' }}</textarea></label></div>\n<div class="form-actions full"><a class="button ghost" href="{% if machine %}/machines/{{ machine.id }}{% else %}/machines{% endif %}">Cancel</a><button class="button" type="submit">{% if machine %}Save Machine{% else %}Create Machine{% endif %}</button></div>\n</form>\n{% endblock %}\n''')

(ROOT / 'templates/machine_detail.html').write_text('''{% extends "base.html" %}\n{% block title %}{{ machine.name }} · PartsLink Global{% endblock %}\n{% block content %}\n<section class="workspace-heading"><div><p class="eyebrow">{{ machine.machine_number }}</p><h1>{{ machine.name }}</h1><p><a href="/customers/{{ machine.customer_id }}">{{ machine.customer_name }}</a>{% if machine.customer_company %} · {{ machine.customer_company }}{% endif %}</p></div><div class="workspace-heading-actions"><a class="button ghost" href="/machines/{{ machine.id }}/edit">Edit Machine</a><a class="button" href="/jobs/new?customer_id={{ machine.customer_id }}&machine_id={{ machine.id }}">＋ New Job</a></div></section>\n<section class="job-summary-grid"><article class="context-card"><span>Manufacturer</span><strong>{{ machine.manufacturer or '—' }}</strong><small>{{ machine.model or 'No model entered' }}</small></article><article class="context-card"><span>VIN / PIN / Serial</span><strong>{{ machine.vin_pin_serial or '—' }}</strong><small>{{ machine.year or 'Year not entered' }}</small></article><article class="context-card"><span>Engine</span><strong>{{ machine.engine or '—' }}</strong><small>{{ machine.engine_serial or 'No engine serial' }}</small></article><article class="context-card"><span>Transmission</span><strong>{{ machine.transmission or '—' }}</strong><small>{% if machine.active %}Active profile{% else %}Inactive profile{% endif %}</small></article></section>\n<section class="panel"><div class="panel-heading"><div><p class="eyebrow">DETAILS</p><h2>Machine Information</h2></div><form method="post" action="/machines/{{ machine.id }}/status"><input type="hidden" name="active" value="{% if machine.active %}0{% else %}1{% endif %}"><button class="button ghost" type="submit">{% if machine.active %}Deactivate{% else %}Reactivate{% endif %}</button></form></div><div class="customer-profile-grid"><div class="full"><span>Component Details</span><strong>{{ machine.component_details or '—' }}</strong></div><div class="full"><span>Notes</span><strong>{{ machine.notes or '—' }}</strong></div></div></section>\n<section class="panel"><div class="panel-heading"><div><p class="eyebrow">JOBS</p><h2>Machine Jobs</h2></div></div>{% if jobs %}<div class="customer-record-list">{% for job in jobs %}<a class="customer-record-row" href="/jobs/{{ job.id }}/basket"><div><strong>{{ job.job_number }}</strong><span>{{ job.created_date }}</span></div><div><strong>{{ job.status }}</strong><span>{{ job.notes or '' }}</span></div></a>{% endfor %}</div>{% else %}<p>No jobs have been created for this machine.</p>{% endif %}</section>\n<section class="panel"><div class="panel-heading"><div><p class="eyebrow">DOCUMENTS</p><h2>Quotes &amp; Invoices</h2></div></div><div class="machine-document-columns"><div><h3>Quotes</h3>{% if quotes %}{% for quote in quotes %}<a class="customer-record-row" href="/quotes/{{ quote.id }}/documents"><div><strong>{{ quote.quote_number }}</strong><span>{{ quote.quote_date }}</span></div><div><strong>${{ '%.2f'|format(quote.customer_total) }}</strong><span>{{ quote.status }}</span></div></a>{% endfor %}{% else %}<p>No quotes.</p>{% endif %}</div><div><h3>Invoices</h3>{% if invoices %}{% for invoice in invoices %}<a class="customer-record-row" href="/invoices/{{ invoice.id }}/documents"><div><strong>{{ invoice.invoice_number }}</strong><span>{{ invoice.invoice_date }}</span></div><div><strong>${{ '%.2f'|format(invoice.customer_total) }}</strong><span>{{ invoice.status }}</span></div></a>{% endfor %}{% else %}<p>No invoices.</p>{% endif %}</div></div></section>\n{% endblock %}\n''')

