# 7) Version and changelog
(ROOT / 'VERSION').write_text('1.1.0-alpha.1\n')
changelog = ROOT / 'CHANGELOG.md'
current = changelog.read_text() if changelog.exists() else '# Changelog\n'
entry = '''\n## Commit 0010 — Machine Registry Foundation\n\n- Added reusable customer-linked machine profiles.\n- Added machine list, create, detail, edit, activate, and deactivate workflows.\n- Added machine selection to new jobs.\n- New equipment entered on a job automatically becomes a reusable machine profile.\n- Linked jobs, quotes, and invoices to machine records.\n- Backfilled machine profiles from existing job equipment data.\n- Added Machines navigation and customer machine lists.\n- Purchase orders are not included.\n\n'''
if 'Commit 0010 — Machine Registry Foundation' not in current:
    if current.startswith('# Changelog'):
        current = '# Changelog\n' + entry + current[len('# Changelog\n'):]
    else:
        current = entry + current
    changelog.write_text(current)

